// --- Automatické vyplnění hotelové karty z e-mailu nebo PDF -----------------
// Rozbor textu dělá stejná funkce jako v objednávkách (parseServiceText /
// parseServiceDocument v lib/ai.js). Co se tam liší, jsou POLE, do kterých to
// padá — a hlavně jedna věc kolem peněz, na kterou je potřeba dát pozor:
//
//   offerCalc.getEffectiveCostDbl: (pricePerNightDbl + cityTax) * nights / 2
//
// Cena i city tax se u DBL dělí dvěma. Obě políčka jsou tedy "za POKOJ a noc",
// ne za osobu — přestože u city tax je v popisku napsáno "/p/night". Když AI
// vrátí city tax za osobu, musí se sem zapsat dvojnásobek, jinak vyjde poloviční.
// U SNGL se nedělí nic, tam jde částka tak, jak přišla.
//
// Žádná z těchto funkcí nic neukládá ani nepočítá cenu nabídky — jen připraví
// návrh, který uživatel v okně odklikne. Peníze jsou v tom okně předem
// NEZAŠKRTNUTÉ (viz MONEY_KEYS níže).

// Číslo z textu; prázdný řetězec, když to číslo není nebo je nula.
// --- E-mailové adresy z vloženého textu ------------------------------------
// Zadání: do kontaktu na kartě má jít adresa toho, KDO e-mail poslal. Ve
// vloženém e-mailu jich bývá víc (hlavička, kopie, patička, podpis) a AI si
// z nich umí vybrat špatně, proto si odesílatele hledáme sami z hlavičky a
// zbytek nabídneme jen jako další možnost.

// Naše vlastní adresy — do kontaktu na dodavatele nikdy nepatří.
// Doplňuje se sem, kdyby přibyla další adresa firmy.
const OWN_EMAIL_PATTERNS = [
  /@tour-pragenses\.com$/i,
  /^helena\.maria\.brito@gmail\.com$/i,
  /^filipdlask@gmail\.com$/i,
];
const isOwnEmail = (addr) => OWN_EMAIL_PATTERNS.some(re => re.test(String(addr || '').trim()));

const EMAIL_RE = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;

// Řádek odesílatele v běžných jazycích, ve kterých nám hotely píšou.
// Ošetřen i tvar 'From: "Radisson Blu" <groups@radisson.no>'.
const SENDER_LINE_RE = /^\s*(?:from|de|od|von|da|van|fra|远)\s*:(.*)$/i;

// Vrátí { sender, others } — adresa odesílatele a ostatní nalezené adresy,
// obojí bez našich vlastních a bez duplicit.
const emailsFromText = (text) => {
  const src = String(text || '');
  let sender = '';
  for (const line of src.split(/\r?\n/)) {
    const m = line.match(SENDER_LINE_RE);
    if (!m) continue;
    const found = (m[1].match(EMAIL_RE) || []).map(a => a.trim()).filter(a => !isOwnEmail(a));
    if (found.length > 0) { sender = found[0]; break; }
  }
  const seen = new Set();
  const others = [];
  for (const raw of (src.match(EMAIL_RE) || [])) {
    const addr = raw.trim();
    const key = addr.toLowerCase();
    if (isOwnEmail(addr) || key === sender.toLowerCase() || seen.has(key)) continue;
    seen.add(key);
    others.push(addr);
  }
  return { sender, others };
};

const fillNum = (v) => {
  const n = parseFloat(String(v === undefined || v === null ? '' : v).replace(',', '.').trim());
  return isFinite(n) && n > 0 ? String(n) : '';
};

// Datum přijímáme jen v přesném tvaru YYYY-MM-DD, jak ho AI slibuje vracet.
const fillDate = (v) => {
  const s = String(v || '').trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : '';
};

// "1 per 20" (tvar z AI) -> "20+1" (tvar, který čeká políčko FOC v nabídce).
// "none", prázdno nebo cokoliv nerozpoznaného -> nevyplňovat nic.
const focToRatio = (foc) => {
  const m = String(foc || '').match(/(\d+)\s*(?:per|za|\/)\s*(\d+)/i);
  return m ? `${m[2]}+${m[1]}` : '';
};

// Nabídka zná u FOC jen SNGL a DBL. Twin i triple padají na DBL.
const focRoomForOffer = (occ) => (String(occ || '').toLowerCase() === 'sngl' ? 'sngl' : 'dbl');

// Noci: co řekla AI, jinak dopočet z dat pobytu.
const nightsForOffer = (parsed) => {
  const n = parseInt(parsed.nights, 10);
  if (isFinite(n) && n > 0) return String(n);
  const from = fillDate(parsed.dateFrom);
  const to = fillDate(parsed.dateTo);
  if (from && to) {
    const diff = Math.round((new Date(to) - new Date(from)) / 86400000);
    if (diff > 0) return String(diff);
  }
  return '';
};

// Termín bezplatného storna: buď konkrétní datum, nebo "X dní před příjezdem".
const cancellationForOffer = (parsed) => {
  const exact = fillDate(parsed.cancellationDate);
  if (exact) return exact;
  const days = parseInt(parsed.cancellationDays, 10);
  const from = fillDate(parsed.dateFrom);
  if (isFinite(days) && days > 0 && from) {
    const d = new Date(from + 'T00:00:00');
    d.setDate(d.getDate() - days);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }
  return '';
};

// City tax: AI vrací částku a k ní typ (za osobu / za pokoj / procenta).
// Vrací hodnoty pro obě políčka nabídky a k nim vysvětlivku, aby bylo v okně
// vidět, odkud se číslo vzalo.
const cityTaxForOffer = (parsed) => {
  const none = { dbl: '', sngl: '', noteDbl: '', noteSngl: '' };
  if (String(parsed.cityTaxIncluded || '').toLowerCase() === 'included') {
    return { ...none, noteDbl: 'podle textu je city tax v ceně — nevyplňuji' };
  }
  const raw = fillNum(parsed.cityTax);
  if (!raw) return none;
  const val = parseFloat(raw);
  const type = String(parsed.cityTaxType || 'per_person').toLowerCase();

  if (type === 'percent') {
    const dblPrice = fillNum(parsed.pricePerDblRoom) || fillNum(parsed.pricePerTwnRoom);
    const snglPrice = fillNum(parsed.pricePerSnglRoom);
    const share = String(val / 100);
    return {
      dbl: dblPrice ? `=${dblPrice}*${share}` : '',
      sngl: snglPrice ? `=${snglPrice}*${share}` : '',
      noteDbl: `${val} % z ceny pokoje`,
      noteSngl: `${val} % z ceny pokoje`,
    };
  }
  if (type === 'per_room') {
    return { dbl: String(val), sngl: String(val), noteDbl: 'za pokoj a noc', noteSngl: 'za pokoj a noc' };
  }
  // per_person (výchozí): dvoulůžkový pokoj = 2 osoby, jednolůžkový = 1 osoba
  return {
    dbl: String(val * 2),
    sngl: String(val),
    noteDbl: `${val} za osobu × 2 osoby v pokoji`,
    noteSngl: `${val} za osobu`,
  };
};

// Pole, u kterých se v potvrzovacím okně NEzaškrtne políčko samo. Všechno, co
// se dotýká výpočtu ceny, musí uživatel odklepnout vědomě.
const MONEY_KEYS = new Set(['pricePerNightDbl', 'pricePerNightSngl', 'cityTax', 'cityTaxSngl', 'currency']);

// Z odpovědi AI sestaví řádky návrhu. Pole, ke kterým AI nic nenašla, se
// vynechají úplně — v okně má být vidět jen to, co se opravdu dá vyplnit.
const buildFillRows = (parsed, item, sourceText) => {
  const tax = cityTaxForOffer(parsed);
  // Odesílatel z hlavičky má přednost před adresou, kterou vybrala AI.
  // U PDF hlavička není, tam zůstane jen to, co našla AI.
  const mails = emailsFromText(sourceText);
  const aiMail = String(parsed.email || '').trim();
  const primaryMail = mails.sender || (isOwnEmail(aiMail) ? '' : aiMail);
  const otherMails = mails.others.filter(a => a.toLowerCase() !== primaryMail.toLowerCase());
  const priceDbl = fillNum(parsed.pricePerDblRoom);
  const priceTwn = fillNum(parsed.pricePerTwnRoom);
  const cur = String(parsed.currency || '').trim().toUpperCase();
  const foc = focToRatio(parsed.hotelFoc);

  const defs = [
    { key: 'city',                 label: 'Město',            value: String(parsed.city || '').trim() },
    { key: 'name',                 label: 'Název hotelu',     value: String(parsed.name || '').trim() },
    { key: 'dateFrom',             label: 'Datum od',         value: fillDate(parsed.dateFrom) },
    { key: 'dateTo',               label: 'Datum do',         value: fillDate(parsed.dateTo) },
    { key: 'nights',               label: 'Počet nocí',       value: nightsForOffer(parsed) },
    { key: 'pricePerNightDbl',     label: 'Cena/noc DBL',     value: priceDbl || priceTwn,
      hint: priceDbl ? 'za pokoj a noc' : 'za pokoj a noc — z ceny TWN, cena DBL v textu nebyla' },
    { key: 'pricePerNightSngl',    label: 'Cena/noc SNGL',    value: fillNum(parsed.pricePerSnglRoom), hint: 'za pokoj a noc' },
    { key: 'cityTax',              label: 'City tax DBL',     value: tax.dbl, hint: tax.noteDbl },
    { key: 'cityTaxSngl',          label: 'City tax SNGL',    value: tax.sngl, hint: tax.noteSngl },
    { key: 'currency',             label: 'Měna',             value: CURRENCIES.includes(cur) ? cur : '' },
    { key: 'cancellationDeadline', label: 'Free cancel',      value: cancellationForOffer(parsed) },
    { key: 'focRatio',             label: 'FOC',              value: foc },
    { key: 'focRoomType',          label: 'FOC — typ pokoje', value: foc ? focRoomForOffer(parsed.hotelFocOccupancy) : '' },
    { key: '__email',              label: 'Kontaktní e-mail', value: primaryMail,
      hint: mails.sender ? 'odesílatel e-mailu' : (primaryMail ? 'nalezeno v textu' : '') },
    ...otherMails.map((addr, i) => ({ key: `__email${i + 2}`, label: 'Další e-mail', value: addr, hint: 'z textu' })),
    { key: '__note',               label: 'Poznámka',         value: String(parsed.notes || '').trim() },
  ];

  return defs
    .filter(d => d.value !== '')
    .map(d => ({ ...d, current: fillCurrentValue(item, d.key), checked: !MONEY_KEYS.has(d.key) && !/^__email\d+$/.test(d.key) }));
};

// Co je v kartě teď — pro sloupec "teď" v potvrzovacím okně.
const fillCurrentValue = (item, key) => {
  if (!item) return '';
  if (key.startsWith('__email')) {
    const list = item.contactEmails || (item.contactEmail ? [item.contactEmail] : []);
    return list.join(', ');
  }
  if (key === '__note') {
    const n = asNoteEntries(item.noteEntries, item.note).length;
    return n > 0 ? `${n} zápis(ů)` : '';
  }
  if (key === 'focRoomType') return item.focRoomType === 'sngl' ? 'SNGL' : item.focRoomType === 'dbl' ? 'DBL' : '';
  const v = item[key];
  return v === undefined || v === null ? '' : String(v);
};

// Hodnota tak, jak se ukáže v okně (data česky, ne YYYY-MM-DD).
const fillDisplayValue = (key, value) => {
  if (key === 'dateFrom' || key === 'dateTo' || key === 'cancellationDeadline') {
    return /^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value.slice(8, 10)}.${value.slice(5, 7)}.${value.slice(0, 4)}` : value;
  }
  if (key === 'focRoomType') return value === 'sngl' ? 'SNGL' : 'DBL';
  return value;
};

// Částka zapsaná ručně může mít desetinnou čárku i mezery mezi tisíci
// ("10 000,50"). Bez odstranění mezer by parseFloat přečetl jen "10", takže
// součet záloh vycházel špatně. Čte se tímhle jedním způsobem všude, aby
// karta i souhrn ukazovaly stejné číslo.
const readAmount = (v) => {
  const cleaned = String(v === 0 ? '0' : (v || ''))
    .replace(/[\s\u00a0\u202f\u2009]/g, '')
    .replace(',', '.');
  return parseFloat(cleaned) || 0;
};

const DepositRows = ({ item, onChange, colors }) => {
  // Deposits are paid in INSTALMENTS — hotels and buses alike — so this is a
  // list, not a single amount. Stored on the item as `deposits`; the currency
  // is not repeated per row because it always follows the item's own currency.
  const rows = Array.isArray(item.deposits) ? item.deposits : [];
  const set = (next) => onChange('deposits', next);
  const add = () => set([...rows, { id: Date.now() + Math.random(), amount: '', date: '', method: '' }]);
  const upd = (id, field, v) => set(rows.map(r => (r.id === id ? { ...r, [field]: v } : r)));
  const del = (id) => set(rows.filter(r => r.id !== id));
  const total = rows.reduce((s, r) => s + readAmount(r.amount), 0);
  const termsFilled = String(item.depositTerms || '').trim() !== '';

  const small = { fontSize: 10, padding: '2px 4px', border: `1px solid ${colors.border}`, borderRadius: 4 };
  const lbl = { fontSize: 9, color: colors.muted };
  const cur = item.currency || 'EUR';

  return (
    <div style={{ flexBasis: '100%', display: 'flex', flexDirection: 'column', gap: 3, marginTop: 2 }}>
      {rows.map((r, i) => {
        const filled = String(r.amount || '').trim() !== '';
        return (
          <div key={r.id} style={{ display: 'flex', alignItems: 'center', gap: 4, flexWrap: 'wrap',
                                   padding: '1px 5px', borderRadius: 4,
                                   background: filled ? '#e8f5e9' : 'transparent' }}>
            <span style={{ ...lbl, width: 46 }}>{i === 0 ? 'Zálohy:' : ''}</span>
            <input type="text" inputMode="decimal" placeholder="0" value={r.amount || ''}
              onInput={decimalInput}
              onChange={e => upd(r.id, 'amount', e.target.value)}
              style={{ ...small, width: 56, textAlign: 'right' }} />
            <span style={lbl}>{cur}</span>
            <span style={{ ...lbl, marginLeft: 2 }}>zaplaceno:</span>
            <DateDMY dateKey={`dep-${item.id}-${r.id}`} value={r.date || ''} colors={colors}
              onChange={v => upd(r.id, 'date', v)} />
            <select value={r.method || ''} onChange={e => upd(r.id, 'method', e.target.value)}
              title="Čím bylo zaplaceno" style={small}>
              {PAYMENT_METHODS.map(m => <option key={m.value} value={m.value}>{m.label}</option>)}
            </select>
            <button type="button" onClick={() => del(r.id)} title="Smazat tuto splátku"
              style={{ ...small, cursor: 'pointer', color: '#b91c1c', background: '#fff', lineHeight: 1 }}>✕</button>
          </div>
        );
      })}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ ...lbl, width: 46 }}>{rows.length === 0 ? 'Zálohy:' : ''}</span>
        <button type="button" onClick={add}
          style={{ ...small, cursor: 'pointer', background: '#fff', color: colors.primary }}>+ splátka</button>
        {rows.length > 1 && (
          <span style={{ fontSize: 10, color: colors.text, fontWeight: 600 }}>
            celkem {Math.round(total * 100) / 100} {cur}
          </span>
        )}
      </div>
      {/* Co dodavatel požaduje — vlastními slovy, jedno pole na celou kartu.
          Je to poznámka, ne číslo: nic se z ní nepočítá a do klientského PDF
          se nedostane. Vyplněná se podbarví, aby ji bylo vidět. */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 4,
                    padding: '1px 5px', borderRadius: 4,
                    background: termsFilled ? '#fff8e1' : 'transparent' }}>
        <span style={{ ...lbl, width: 46 }}>Podmínky:</span>
        <input type="text" placeholder="např. 30 % při konfirmaci, zbytek 30 dní před příjezdem"
          title="Podmínky záloh u tohoto dodavatele — jen pro vás, do nabídky pro klienta se netiskne"
          value={item.depositTerms || ''}
          onChange={e => onChange('depositTerms', e.target.value)}
          style={{ ...small, flex: 1, minWidth: 160 }} />
      </div>
    </div>
  );
};

function BookingStatusSelect({ value, onChange, colors }) {
  const s = BOOKING_STATUS.find(o => o.value === (value || '')) || BOOKING_STATUS[0];
  return (
    <select value={value || ''} onChange={e => onChange(e.target.value)} title="Stav této položky"
      style={{ fontSize: 10, padding: '2px 4px', borderRadius: 4,
               border: `1px solid ${s.border || colors.border}`,
               background: s.bg, color: s.color || colors.muted }}>
      {BOOKING_STATUS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

const decimalInput = (e) => {
  const val = e.target.value;
  const normalized = val.replace(/,/g, '.');
  if (normalized !== val) e.target.value = normalized;
};

// Reusable input that accepts plain numbers or "=formula" expressions, and converts
// the formula to its computed result on blur, so the field shows the computed number directly.
// Defined at module level (not inside OfferDetail) so it keeps a stable identity across
// re-renders and inputs don't lose focus on every keystroke.
const FormulaField = ({ value, onChange, placeholder, colors }) => {
  const style = { width: '100%', padding: '6px 8px', border: `1px solid ${colors.border}`, borderRadius: 6, fontSize: 13, fontFamily: 'Georgia, serif', boxSizing: 'border-box' };
  return (
    <input type="text" placeholder={placeholder} value={value} onChange={onChange} onInput={decimalInput}
      onBlur={e => {
        const v = e.target.value;
        if (String(v).trim().startsWith('=')) {
          const computed = evalAmount(v);
          onChange({ target: { value: String(Math.round(computed * 100) / 100) } });
        }
      }}
      style={style} />
  );
};

const fmtDateBR = (d) => { if (!d || d.length < 10) return d; const [y, m, day] = d.split('-'); return `${day}/${m}/${y}`; };

// Vlastní malý kalendář. Kalendář vestavěný v prohlížeči se v některých
// prostředích otevřít odmítne, tenhle funguje vždycky stejně.
const CAL_MONTHS = ['leden', 'únor', 'březen', 'duben', 'květen', 'červen',
                    'červenec', 'srpen', 'září', 'říjen', 'listopad', 'prosinec'];
const CAL_DAYS = ['Po', 'Út', 'St', 'Čt', 'Pá', 'So', 'Ne'];

const calISO = (y, m, d) =>
  `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

const CalendarPopup = ({ value, onPick, onClose, colors }) => {
  const base = (value && value.length === 10) ? new Date(value + 'T00:00:00') : new Date();
  const [view, setView] = React.useState({ y: base.getFullYear(), m: base.getMonth() });
  const boxRef = React.useRef(null);

  React.useEffect(() => {
    const away = (e) => { if (boxRef.current && !boxRef.current.contains(e.target)) onClose(); };
    const esc = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('mousedown', away);
    document.addEventListener('keydown', esc);
    return () => {
      document.removeEventListener('mousedown', away);
      document.removeEventListener('keydown', esc);
    };
  }, [onClose]);

  const shift = (months) => setView(v => {
    const d = new Date(v.y, v.m + months, 1);
    return { y: d.getFullYear(), m: d.getMonth() };
  });

  const first = new Date(view.y, view.m, 1);
  // Pondělí je první sloupec, neděle poslední.
  const lead = (first.getDay() + 6) % 7;
  const days = new Date(view.y, view.m + 1, 0).getDate();
  const today = new Date();
  const todayISO = calISO(today.getFullYear(), today.getMonth(), today.getDate());

  const cells = [];
  for (let i = 0; i < lead; i++) cells.push(null);
  for (let d = 1; d <= days; d++) cells.push(d);

  const navBtn = (label, fn, title) => (
    <button type="button" onClick={fn} title={title}
      style={{ border: `1px solid ${colors.border}`, background: colors.white, borderRadius: 4,
               cursor: 'pointer', fontSize: 12, lineHeight: 1, padding: '3px 6px',
               fontFamily: 'inherit', color: colors.text }}>{label}</button>
  );

  return (
    <div ref={boxRef}
      style={{ position: 'absolute', top: '100%', left: 0, marginTop: 4, zIndex: 1000,
               background: colors.white, border: `1px solid ${colors.border}`,
               borderRadius: 8, padding: 8, width: 232,
               boxShadow: '0 6px 20px rgba(0,0,0,0.15)', fontFamily: 'Georgia, serif' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginBottom: 6 }}>
        {navBtn('«', () => shift(-12), 'O rok zpět')}
        {navBtn('‹', () => shift(-1), 'O měsíc zpět')}
        <div style={{ flex: 1, textAlign: 'center', fontSize: 12, fontWeight: 700,
                      color: colors.primary, whiteSpace: 'nowrap' }}>
          {CAL_MONTHS[view.m]} {view.y}
        </div>
        {navBtn('›', () => shift(1), 'O měsíc vpřed')}
        {navBtn('»', () => shift(12), 'O rok vpřed')}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
        {CAL_DAYS.map((d, i) => (
          <div key={d} style={{ fontSize: 10, textAlign: 'center', fontWeight: 700,
                                color: i > 4 ? colors.danger : colors.muted, padding: '2px 0' }}>{d}</div>
        ))}
        {cells.map((d, i) => {
          if (d === null) return <div key={'e' + i} />;
          const iso = calISO(view.y, view.m, d);
          const isSel = iso === value;
          const isToday = iso === todayISO;
          const weekend = ((lead + d - 1) % 7) > 4;
          return (
            <button key={iso} type="button" onClick={() => onPick(iso)}
              style={{
                padding: '4px 0', fontSize: 12, cursor: 'pointer', borderRadius: 4,
                fontFamily: 'inherit',
                border: isToday ? `1px solid ${colors.primary}` : '1px solid transparent',
                background: isSel ? colors.primary : 'transparent',
                color: isSel ? colors.white : (weekend ? colors.danger : colors.text),
                fontWeight: isSel || isToday ? 700 : 400,
              }}>{d}</button>
          );
        })}
      </div>

      <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
        <button type="button" onClick={() => onPick(todayISO)}
          style={{ flex: 1, padding: '4px 0', fontSize: 11, cursor: 'pointer', borderRadius: 5,
                   border: `1px solid ${colors.border}`, background: colors.white,
                   fontFamily: 'inherit', color: colors.primary }}>Dnes</button>
        <button type="button" onClick={() => onPick('')}
          style={{ flex: 1, padding: '4px 0', fontSize: 11, cursor: 'pointer', borderRadius: 5,
                   border: `1px solid ${colors.border}`, background: colors.white,
                   fontFamily: 'inherit', color: colors.muted }}>Vymazat</button>
      </div>
    </div>
  );
};

// Date input in DD.MM.YYYY order — always consistent regardless of browser/OS locale
const DateDMY = ({ value, onChange, colors, dateKey }) => {
  const toDisplay = (v) => {
    if (v && v.length === 10) {
      const [y, m, d] = v.split('-');
      return `${d}.${m}.${y}`;
    }
    return '';
  };
  const toISO = (v) => {
    const clean = v.replace(/[^\d]/g, '');
    if (clean.length === 8) {
      const d = clean.slice(0, 2), m = clean.slice(2, 4), y = clean.slice(4, 8);
      if (!isNaN(new Date(`${y}-${m}-${d}`))) return `${y}-${m}-${d}`;
    }
    return null;
  };
  const getWeekday = (v) => {
    if (v && v.length === 10) {
      const d = new Date(v + 'T00:00:00');
      if (!isNaN(d)) return d.toLocaleDateString('en-US', { weekday: 'short' });
    }
    return '';
  };
  const [weekday, setWeekday] = React.useState(() => getWeekday(value));
  const inputRef = React.useRef(null);
  const prevValue = React.useRef(value);
  React.useEffect(() => {
    if (prevValue.current !== value && inputRef.current && document.activeElement !== inputRef.current) {
      inputRef.current.value = toDisplay(value);
      prevValue.current = value;
      setWeekday(getWeekday(value));
    }
  }, [value]);

  // Datum jde psát i vyklikat z kalendáře.
  const [calOpen, setCalOpen] = React.useState(false);
  const applyPicked = (iso) => {
    if (inputRef.current) inputRef.current.value = iso ? toDisplay(iso) : '';
    prevValue.current = iso;
    setWeekday(iso ? getWeekday(iso) : '');
    onChange(iso);
    setCalOpen(false);
  };

  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, position: 'relative' }}>
      <input
        ref={inputRef}
        type="text"
        placeholder="DD.MM.RRRR"
        defaultValue={toDisplay(value)}
        onBlur={e => {
          const iso = toISO(e.target.value);
          if (iso) { e.target.value = toDisplay(iso); onChange(iso); setWeekday(getWeekday(iso)); }
        }}
        style={{ padding: '6px 8px', border: `1px solid ${colors.border}`, borderRadius: 6, fontSize: 13, fontFamily: 'Georgia, serif', width: 100, boxSizing: 'border-box' }}
      />
      <button
        type="button"
        onClick={() => setCalOpen(o => !o)}
        title="Vybrat z kalendáře"
        style={{ padding: '3px 6px', border: `1px solid ${colors.border}`, borderRadius: 5,
                 background: calOpen ? '#f0ede8' : colors.white, cursor: 'pointer',
                 fontSize: 13, lineHeight: 1 }}
      >📅</button>
      {calOpen && (
        <CalendarPopup value={value} colors={colors}
          onPick={applyPicked} onClose={() => setCalOpen(false)} />
      )}
      {weekday && <span style={{ fontSize: 11, color: colors.muted, fontWeight: 600, whiteSpace: 'nowrap' }}>{weekday}</span>}
    </span>
  );
};

// Small drag-and-drop / click-to-upload control for attaching a hotel confirmation
// (e.g. an email saved as PDF, a voucher, or a screenshot) directly to an itinerary item.
const HotelAttachment = ({ item, onUpload, onRemove, colors }) => {
  const [uploading, setUploading] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const [dragOver, setDragOver] = React.useState(false);
  const [error, setError] = React.useState('');
  const inputRef = React.useRef(null);

  const handleFile = async (file) => {
    if (!file) return;
    setError('');
    setProgress(0);
    setUploading(true);
    try {
      await onUpload(file, (pct) => setProgress(pct));
    } catch (e) {
      setError(e.message || 'Nahrání selhalo');
      console.error('Attachment upload failed:', e);
    } finally {
      setUploading(false);
    }
  };

  // Combine legacy single-file field (older items) with the new attachments array,
  // so nothing already uploaded ever disappears.
  const files = [
    ...(item.confirmationFileUrl ? [{ url: item.confirmationFileUrl, name: item.confirmationFileName, path: item.confirmationFilePath, legacy: true }] : []),
    ...(item.attachments || []),
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 2, alignItems: 'flex-start' }}>
      {files.map((f, i) => (
        <div key={f.path || i} style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <a href={f.url} target="_blank" rel="noopener noreferrer"
            title={f.name}
            style={{ fontSize: 10, color: colors.primary, textDecoration: 'underline', maxWidth: 100, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            📎 {f.name || 'potvrzení'}
          </a>
          <button onClick={() => onRemove(f)} title="Odebrat přílohu"
            style={{ fontSize: 10, color: colors.danger, background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>✕</button>
        </div>
      ))}
      <div
        onDragOver={e => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={e => {
          e.preventDefault(); setDragOver(false);
          const file = e.dataTransfer.files && e.dataTransfer.files[0];
          if (file) handleFile(file);
        }}
        onClick={() => !uploading && inputRef.current && inputRef.current.click()}
        title={error || 'Přetáhni sem email/PDF potvrzení, nebo klikni pro výběr souboru'}
        style={{
          fontSize: 10, padding: '2px 6px', borderRadius: 4, cursor: uploading ? 'default' : 'pointer',
          border: `1px dashed ${error ? colors.danger : dragOver ? colors.primary : colors.border}`,
          background: dragOver ? '#f0f7ff' : 'transparent',
          color: error ? colors.danger : colors.muted, whiteSpace: 'nowrap',
          maxWidth: 160, overflow: 'hidden', textOverflow: 'ellipsis',
        }}>
        {uploading ? `⏳ Nahrávám… ${progress}%` : error ? '⚠ ' + error : (files.length > 0 ? '📎 + Další příloha' : '📎 Potvrzení')}
        <input ref={inputRef} type="file" style={{ display: 'none' }}
          onChange={e => { const f = e.target.files && e.target.files[0]; if (f) handleFile(f); e.target.value = ''; }} />
      </div>
    </div>
  );
};

// --- Poznámky jako seznam zápisů -----------------------------------------
// Poznámka už není jeden dlouhý text, ale řada zápisů. Každý zápis má datum,
// autora a text. Nejnovější je nahoře, starší se nikdy nepřepisují.
//
// Sbaleně je z každého zápisu vidět jeden řádek, aby šlo na první pohled
// poznat, že v poznámce něco je, bez klikání. Kliknutím se zápis rozbalí.
const NOTE_AUTHORS = [
  { code: 'HD', name: 'Helena Dlasková',   color: '#1a3a5c', bg: '#e6f1fb', border: '#1a3a5c' },
  // Zlatá z loga je na bílém pozadí špatně čitelná, proto tmavší odstín na
  // text a plná zlatá jen na tlačítko.
  { code: 'FD', name: 'Filip Dlask',       color: '#7a5c0a', bg: '#c8a84b', border: '#a8862b' },
  { code: 'HŠ', name: 'Helena Škorkovská', color: '#a11a1a', bg: '#fceaea', border: '#a11a1a' },
];

const noteAuthor = (code) => NOTE_AUTHORS.find(a => a.code === code) || null;

const WEEKDAYS_CS = ['Neděle', 'Pondělí', 'Úterý', 'Středa', 'Čtvrtek', 'Pátek', 'Sobota'];

const noteStamp = (d = new Date()) => {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}.${mm}.${d.getFullYear()} ${WEEKDAYS_CS[d.getDay()]}`;
};

// Starší poznámky byly jeden text. Zobrazí se jako jediný nejstarší zápis
// bez autora — text zůstává celý, jen není rozdělený po dnech.
const asNoteEntries = (entries, legacyText) => {
  if (Array.isArray(entries)) return entries;
  const t = (legacyText || '').trim();
  if (!t) return [];
  return [{ id: 'legacy', stamp: '', author: '', text: legacyText }];
};

const noteEntriesToText = (list) => (list || [])
  .map(e => [[e.stamp, e.author].filter(Boolean).join(' - '), e.text].filter(Boolean).join('\n'))
  .filter(Boolean).join('\n\n');

const NoteLog = ({ entries, onChange, colors, compact, onMakeTask, sourceLabel }) => {
  const [openIds, setOpenIds] = React.useState(() => new Set());
  const [expandAll, setExpandAll] = React.useState(false);
  const [showOlder, setShowOlder] = React.useState(false);
  const focusId = React.useRef(null);
  const taRefs = React.useRef({});

  const list = Array.isArray(entries) ? entries : [];

  // Označenou větu vezmeme přednostně; když nic označeno není, celý zápis.
  const makeTask = (entry) => {
    const el = taRefs.current[entry.id];
    let picked = '';
    if (el && el.selectionStart !== el.selectionEnd) {
      picked = (entry.text || '').slice(el.selectionStart, el.selectionEnd);
    }
    onMakeTask({
      text: (picked || entry.text || '').trim(),
      source: sourceLabel || '',
      mark: () => onChange(list.map(e => (e.id === entry.id ? { ...e, hasTask: true } : e))),
    });
  };

  const VISIBLE = 5;
  const visible = showOlder ? list : list.slice(0, VISIBLE);
  const hidden = list.length - visible.length;

  const addEntry = (code) => {
    const entry = {
      id: Date.now() + Math.random(),
      stamp: noteStamp(),
      author: code,
      text: '',
      createdAt: new Date().toISOString(),
    };
    focusId.current = entry.id;
    setOpenIds(prev => new Set([...prev, entry.id]));
    setShowOlder(false);
    onChange([entry, ...list]);
  };

  const setText = (id, text) => onChange(list.map(e => (e.id === id ? { ...e, text } : e)));

  const removeEntry = (id) => {
    if (!window.confirm('Smazat tento zápis? Tuhle akci nelze vzít zpět.')) return;
    onChange(list.filter(e => e.id !== id));
  };

  const toggle = (id) => setOpenIds(prev => {
    const s = new Set(prev);
    s.has(id) ? s.delete(id) : s.add(id);
    return s;
  });

  const btnRow = (
    <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
      <span style={{ fontSize: 11, color: colors.muted }}>Nový zápis:</span>
      {NOTE_AUTHORS.map(a => (
        <button key={a.code} type="button" onClick={() => addEntry(a.code)}
          title={`Přidat zápis za ${a.name}`}
          style={{
            padding: '3px 10px', borderRadius: 5, fontSize: 12, fontWeight: 700,
            cursor: 'pointer', background: a.bg, color: a.color,
            border: `1px solid ${a.border}`, fontFamily: 'inherit',
          }}>
          {a.code}
        </button>
      ))}
      {list.length > 1 && (
        <button type="button" onClick={() => setExpandAll(v => !v)}
          style={{ marginLeft: 'auto', padding: '3px 10px', borderRadius: 5, fontSize: 11,
                   cursor: 'pointer', background: 'transparent', color: colors.muted,
                   border: `1px solid ${colors.border}`, fontFamily: 'inherit' }}>
          {expandAll ? 'Sbalit vše' : 'Rozbalit vše'}
        </button>
      )}
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
      {btnRow}
      {list.length === 0 ? (
        <div style={{ fontSize: 12, color: colors.muted, fontStyle: 'italic' }}>
          Zatím žádný zápis.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
          {visible.map(entry => {
            const a = noteAuthor(entry.author);
            const isOpen = expandAll || openIds.has(entry.id);
            const label = [entry.stamp, entry.author].filter(Boolean).join(' - ');
            if (!isOpen) {
              const firstLine = (entry.text || '').split('\n')[0].trim();
              return (
                <div key={entry.id} onClick={() => toggle(entry.id)}
                  title="Kliknutím rozbalit celý zápis"
                  style={{
                    display: 'flex', alignItems: 'baseline', gap: 6, cursor: 'pointer',
                    padding: '3px 6px', borderRadius: 4, background: '#fff',
                    border: `1px solid ${colors.border}`, fontSize: 12,
                    whiteSpace: 'nowrap', overflow: 'hidden',
                  }}>
                  {label && (
                    <span style={{ fontWeight: 700, color: a ? a.color : colors.muted, flexShrink: 0 }}>
                      {label}
                    </span>
                  )}
                  <span style={{ color: colors.text, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                    {firstLine || <em style={{ color: colors.muted }}>(prázdný zápis)</em>}
                  </span>
                </div>
              );
            }
            const rows = Math.min(Math.max((entry.text || '').split('\n').length + 1, 3), 14);
            return (
              <div key={entry.id}
                style={{ padding: '4px 6px', borderRadius: 4, background: '#fff',
                         border: `1px solid ${a ? a.border : colors.border}` }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 3 }}>
                  <span onClick={() => toggle(entry.id)}
                    title="Kliknutím sbalit"
                    style={{ fontWeight: 700, fontSize: 12, cursor: 'pointer',
                             color: a ? a.color : colors.muted }}>
                    {label || 'Starší poznámka'}
                  </span>
                  <div style={{ flex: 1 }} />
                  {entry.hasTask && (
                    <span title="Z tohoto zápisu už vznikl úkol"
                      style={{ fontSize: 10, color: colors.success, fontWeight: 700 }}>✓ úkol</span>
                  )}
                  {onMakeTask && (
                    <button type="button" onClick={() => makeTask(entry)}
                      title="Udělat z tohoto zápisu úkol. Označ myší jednu větu, nebo se vezme celý zápis."
                      style={{ background: 'none', border: `1px solid ${colors.border}`, borderRadius: 4,
                               cursor: 'pointer', color: colors.primary, fontSize: 11, padding: '1px 7px',
                               fontFamily: 'inherit' }}>→ úkol</button>
                  )}
                  <button type="button" onClick={() => removeEntry(entry.id)}
                    title="Smazat tento zápis"
                    style={{ background: 'none', border: 'none', cursor: 'pointer',
                             color: colors.danger, fontSize: 12, padding: 0 }}>✕</button>
                </div>
                <textarea
                  ref={el => {
                    taRefs.current[entry.id] = el;
                    if (el && focusId.current === entry.id) {
                      focusId.current = null;
                      el.focus();
                    }
                  }}
                  value={entry.text || ''}
                  onChange={e => setText(entry.id, e.target.value)}
                  placeholder="Co se stalo, co si o tom myslíme, co je třeba udělat…"
                  rows={rows}
                  style={{ width: '100%', padding: '6px 8px', boxSizing: 'border-box',
                           border: `1px solid ${colors.border}`, borderRadius: 6,
                           fontSize: 13, fontFamily: 'inherit', lineHeight: 1.5,
                           resize: 'vertical' }}
                />
              </div>
            );
          })}
          {hidden > 0 && (
            <button type="button" onClick={() => setShowOlder(true)}
              style={{ alignSelf: 'flex-start', background: 'none', border: 'none',
                       color: colors.primary, cursor: 'pointer', fontSize: 12,
                       padding: '2px 0', fontFamily: 'inherit', textDecoration: 'underline' }}>
              + {hidden} starších
            </button>
          )}
          {showOlder && list.length > VISIBLE && (
            <button type="button" onClick={() => setShowOlder(false)}
              style={{ alignSelf: 'flex-start', background: 'none', border: 'none',
                       color: colors.muted, cursor: 'pointer', fontSize: 12,
                       padding: '2px 0', fontFamily: 'inherit', textDecoration: 'underline' }}>
              Skrýt starší
            </button>
          )}
        </div>
      )}
    </div>
  );
};

// --- Úkoly u nabídky ------------------------------------------------------
// Seznam, ne jedno velké pole, aby se dalo odškrtávat. Hotové se nemažou,
// jen přeškrtnou a spadnou dolů — ať je vidět, co už se udělalo.
const TaskList = ({ todos, onChange, colors }) => {
  const [draft, setDraft] = React.useState({ text: '', due: '', who: '' });

  const list = Array.isArray(todos) ? todos : [];
  const open = list.filter(t => !t.done);
  const done = list.filter(t => t.done);

  const add = () => {
    if (!draft.text.trim()) return;
    onChange([{
      id: Date.now() + Math.random(),
      text: draft.text.trim(),
      due: draft.due || '',
      who: draft.who || '',
      done: false,
      createdAt: new Date().toISOString(),
    }, ...list]);
    setDraft({ text: '', due: '', who: '' });
  };

  const upd = (id, field, value) => onChange(list.map(t => (t.id === id ? { ...t, [field]: value } : t)));
  const del = (id) => {
    if (!window.confirm('Smazat tento úkol?')) return;
    onChange(list.filter(t => t.id !== id));
  };

  const small = { fontSize: 12, padding: '4px 7px', border: `1px solid ${colors.border}`, borderRadius: 5, fontFamily: 'inherit' };

  const row = (t) => {
    const a = noteAuthor(t.who);
    const overdue = !t.done && t.due && t.due.length === 10 && t.due < new Date().toISOString().slice(0, 10);
    return (
      <div key={t.id} style={{
        display: 'flex', alignItems: 'center', gap: 8, padding: '5px 7px',
        borderRadius: 5, background: '#fff', border: `1px solid ${colors.border}`,
        opacity: t.done ? 0.55 : 1,
      }}>
        <input type="checkbox" checked={!!t.done} onChange={e => upd(t.id, 'done', e.target.checked)}
          title={t.done ? 'Vrátit mezi nesplněné' : 'Označit jako hotové'}
          style={{ width: 15, height: 15, cursor: 'pointer', flexShrink: 0 }} />
        <input type="text" value={t.text} onChange={e => upd(t.id, 'text', e.target.value)}
          style={{ ...small, flex: 1, border: 'none', background: 'transparent', fontSize: 13,
                   textDecoration: t.done ? 'line-through' : 'none', color: colors.text }} />
        {t.source && (
          <span title={`Vzniklo ze zápisu: ${t.source}`}
            style={{ fontSize: 10, color: colors.muted, whiteSpace: 'nowrap', maxWidth: 150,
                     overflow: 'hidden', textOverflow: 'ellipsis' }}>
            ↩ {t.source}
          </span>
        )}
        <DateDMY dateKey={`todo-${t.id}`} value={t.due || ''} colors={colors}
          onChange={v => upd(t.id, 'due', v)} />
        {overdue && <span style={{ fontSize: 11, color: colors.danger, fontWeight: 700, whiteSpace: 'nowrap' }}>po termínu</span>}
        <select value={t.who || ''} onChange={e => upd(t.id, 'who', e.target.value)}
          title="Kdo to má udělat"
          style={{ ...small, background: a ? a.bg : '#fff', color: a ? a.color : colors.muted, fontWeight: a ? 700 : 400 }}>
          <option value="">kdo?</option>
          {NOTE_AUTHORS.map(x => <option key={x.code} value={x.code}>{x.code}</option>)}
        </select>
        <button type="button" onClick={() => del(t.id)} title="Smazat úkol"
          style={{ background: 'none', border: 'none', cursor: 'pointer', color: colors.danger, fontSize: 12, padding: 0 }}>✕</button>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
        <input type="text" value={draft.text} placeholder="Co je třeba udělat…"
          onChange={e => setDraft(d => ({ ...d, text: e.target.value }))}
          onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); add(); } }}
          style={{ ...small, flex: 1, minWidth: 180, fontSize: 13 }} />
        <DateDMY dateKey="todo-new" value={draft.due} colors={colors}
          onChange={v => setDraft(d => ({ ...d, due: v }))} />
        <select value={draft.who} onChange={e => setDraft(d => ({ ...d, who: e.target.value }))} style={small}>
          <option value="">kdo?</option>
          {NOTE_AUTHORS.map(x => <option key={x.code} value={x.code}>{x.code}</option>)}
        </select>
        <button type="button" onClick={add}
          style={{ ...small, cursor: 'pointer', background: colors.primary, color: '#fff', border: 'none', fontWeight: 600 }}>
          + Přidat
        </button>
      </div>

      {list.length === 0 ? (
        <div style={{ fontSize: 12, color: colors.muted, fontStyle: 'italic' }}>Zatím žádný úkol.</div>
      ) : (
        <>
          {open.map(row)}
          {done.length > 0 && (
            <div style={{ fontSize: 11, color: colors.muted, marginTop: 4 }}>Hotové ({done.length})</div>
          )}
          {done.map(row)}
        </>
      )}
    </div>
  );
};

// Text "Incluído no preço" se skládá z toho, co v nabídce opravdu je.
// Dřív ho generovalo tlačítko, na které se zapomínalo; teď se hlídá sám.
// Text se skládá ze dvou vrstev: řádky, které vznikají z nabídky, a řádky,
// které si tam dopsal člověk. Generované se udržují, dopsané zůstávají.
// Co uživatel z generovaných smazal, se už nevrací.
const mergeIncluded = (generated, currentText, prevGenerated) => {
  const split = (t) => (t || '').split('\n').map(l => l.trim()).filter(Boolean);
  const gen = split(generated);
  const cur = split(currentText);
  const prev = split(prevGenerated);
  const prevSet = new Set(prev);
  const curSet = new Set(cur);
  const extras = cur.filter(l => !prevSet.has(l));
  const removed = new Set(prev.filter(l => !curSet.has(l)));
  return [...gen.filter(l => !removed.has(l)), ...extras].join('\n');
};

const buildIncludedText = (items) => {
  const active = (items || []).filter(it => it.enabled !== false);
  const hotels = active.filter(it => it.subType === 'hotel');
  const tickets = active.filter(it => it.subType === 'ticket' && it.name);
  const groupSvcs = active.filter(it => it.type === 'group' && it.name
    && it.subType !== 'guide_hotel' && it.subType !== 'driver_hotel');
  const hasTax = hotels.some(h => evalAmount(h.cityTax) > 0);
  const lines = [];
  if (hotels.length > 0) lines.push(`Hospedagem em hotéis selecionados, com café da manhã incluído (${hotels.length} ${hotels.length === 1 ? 'hotel' : 'hotéis'}, conforme itinerário)`);
  if (hasTax) lines.push('Taxas municipais (city tax) dos hotéis');
  groupSvcs.forEach(it => lines.push(it.name));
  tickets.forEach(it => lines.push(`1x ${it.name}`));
  lines.push('Assistência da nossa equipe durante toda a viagem');
  return lines.join('\n');
};

